<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); try { $req = request(); $req->merge(["key" => config("services.google_merchant.feed_key")]); echo app("App\Http\Controllers\Api\GoogleMerchantFeedController")->xml($req)->getContent(); } catch (\Throwable $e) { echo get_class($e) . ": " . $e->getMessage() . "\n" . $e->getTraceAsString(); }
